            $ctx=$this->contact($session,$issuer,$project);$prove=function()use($session,$issuer,$project,$ctx,$expectedPage,$expectedThread,$expectedReceipt):void{if($this->contact($session,$issuer,$project)!==$ctx||$this->pageProjection($issuer,$project,$ctx)!==$expectedPage)throw new DomainException('company_project_discussion_unavailable');if($expectedThread!==null){$id=IssuerPolicy::id($expectedThread['id']??null);$actual=$this->threadProjection($issuer,$project,$id,$ctx)+['project_revision'=>(int)$ctx['parent']['revision'],'collection_revision'=>$this->state($issuer,$project)];if($actual!==$expectedThread)throw new DomainException('company_project_discussion_unavailable');}if($expectedReceipt!==null){$key=$expectedReceipt['request_key']??null;if(!is_string($key)||$this->receiptProjection($session,$issuer,$project,$key)!==$expectedReceipt)throw new DomainException('company_project_discussion_unavailable');}};$prove();$this->audit($issuer,$project,'company_project_discussion_response_confirmed',['contact_id'=>$ctx['who']['contact_id']]);$prove();
